sys_security_acl.script:
answer = false;

// Administrator can update all leave requests
if (gs.hasRole('x_2132473_leave_0.admin')) {
    answer = true;
}

// Manager can update requests belonging to their team
else if (gs.hasRole('x_2132473_leave_0.manager')) {

    var employeeGR = new GlideRecord(
        'x_2132473_leave_0_employee'
    );

    if (employeeGR.get(current.getValue('employee'))) {

        var managerGR = new GlideRecord(
            'x_2132473_leave_0_employee'
        );

        managerGR.addQuery('user', gs.getUserID());
        managerGR.addQuery('active', true);
        managerGR.setLimit(1);
        managerGR.query();

        if (managerGR.next()) {
            answer =
                employeeGR.getValue('manager') ==
                managerGR.getUniqueValue();
        }
    }
}
